import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph User + Dev Monthly Meeting- 10/16/24","description":"","frontmatter":{"title":"Ceph User + Dev Monthly Meeting- 10/16/24","date":"2024-10-22T00:00:00.000Z","updated":"2024-10-23T00:00:00.000Z","tags":["Ceph","S3 Rados Gateway","User Group","Community Engagement","Ceph Development"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_-_10_16_24.md","filePath":"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_-_10_16_24.md","lastUpdated":1780459816000}'),l={name:"posts/2024/Ceph_User_+_Dev_Monthly_Meeting_-_10_16_24.md"};function s(n,e,i,h,_,g){return a(),o("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要-ceph用户开发会议-2023年10月" tabindex="-1">会议纪要：Ceph用户开发会议（2023年10月） <a class="header-anchor" href="#会议纪要-ceph用户开发会议-2023年10月" aria-label="Permalink to &quot;会议纪要：Ceph用户开发会议（2023年10月）&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><ul><li><strong>日期与时间</strong>：2023年10月</li><li><strong>主持人</strong>：Laura</li><li><strong>主讲人</strong>：Joseph（来自Bloomberg）</li><li><strong>参会人员</strong>：Ceph社区用户与开发者</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><p>Joseph提出了建立一个专注于S3 Rados Gateway（RGW）的用户开发小组，旨在解决以下问题：</p><ol><li><strong>问题识别与沟通</strong>：集中讨论用户在使用和管理Ceph集群时遇到的问题和Bug。</li><li><strong>功能透明度</strong>：关注S3协议的新功能、变更及其在Ceph中的实现计划和优先级。</li><li><strong>需求与开发对接</strong>：通过建立跟踪器等方式，提高社区对功能需求的可见性，促进用户与开发者的直接对话。</li><li><strong>长期支持与变更管理</strong>：讨论S3协议中功能移除的公告，如S3 select，以及Ceph对这些变更的支持策略。</li></ol><h4 id="讨论要点" tabindex="-1">讨论要点 <a class="header-anchor" href="#讨论要点" aria-label="Permalink to &quot;讨论要点&quot;">​</a></h4><ul><li><strong>Matthew的疑问</strong>：质疑为何需要专门针对S3层建立用户小组，而不是在现有渠道中改进沟通。</li><li><strong>Joseph的回应</strong>：强调S3协议的快速变化和特定用例的需求，以及现有跟踪器和沟通渠道的不足。</li><li><strong>其他参与者的反馈</strong>：建议通过调查和邮件列表来收集具体案例，以验证这一提议的必要性和效果。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>后续行动</strong>：Joseph将在标准周会中与RGW开发团队接触，并准备一份详细的提议，通过用户邮件列表进行讨论。</li><li><strong>调查与反馈</strong>：计划进行一次调查，以收集社区对S3功能需求的反馈，并可能与RGW开发团队合作。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ol><li><strong>邮件沟通</strong>：向Ceph用户和开发者邮件列表发送提议，附带具体案例。</li><li><strong>调查设计</strong>：设计并发布调查问卷，收集社区对S3功能的意见和需求。</li><li><strong>定期会议</strong>：提议建立定期的用户开发会议，如每月或每两个月一次，以跟进新问题和需求。</li></ol><h4 id="其他讨论" tabindex="-1">其他讨论 <a class="header-anchor" href="#其他讨论" aria-label="Permalink to &quot;其他讨论&quot;">​</a></h4><ul><li><strong>用户支持</strong>：建议新用户在遇到问题时通过邮件列表或Slack频道寻求帮助。</li><li><strong>功能跟踪</strong>：强调在Ceph的bug scrub会议中，更新过的跟踪器会得到更多关注。</li></ul><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><p>会议在无进一步问题的情况下提前结束，Joseph感谢大家的参与，并期待未来的进展。</p>',16)])])}const u=t(l,[["render",s]]);export{d as __pageData,u as default};
